// AC1021 (R2007) native section contents captured from an AutoCAD 2007 saved
// empty drawing (DrawingR2007.dwg). AppInfo and AppInfoHistory form a matched
// pair (the history references the AppInfo GUID), so both are embedded verbatim.
using System;

namespace ACadSharp.IO.DWG.DwgStreamWriters;

internal static class Ac21NativeSections
{
internal static readonly byte[] AppInfo = Parse(
		"");

internal static readonly byte[] AppInfoHistory = Parse(
		"");

	// Convert.FromHexString is unavailable under net48/netstandard2.0, so parse manually.
	private static byte[] Parse(string hex)
	{
		byte[] result = new byte[hex.Length / 2];
		for (int i = 0; i < result.Length; i++)
		{
			result[i] = (byte)((HexVal(hex[i * 2]) << 4) | HexVal(hex[i * 2 + 1]));
		}
		return result;
	}

	private static int HexVal(char c)
	{
		if (c >= '0' && c <= '9') { return c - '0'; }
		if (c >= 'a' && c <= 'f') { return c - 'a' + 10; }
		if (c >= 'A' && c <= 'F') { return c - 'A' + 10; }
		throw new FormatException($"Invalid hex char '{c}'");
	}
}
